unsafe extern "C" fn get_encoder_frame_size(
    mut transcoder: *const audio_transcoder_t,
) -> ::core::ffi::c_int {
    if transcoder.is_null() {
        return DEFAULT_AAC_FRAME_SIZE;
    }
    if !(*transcoder).faac_enc.is_null() {
        return faac_adapter_get_frame_samples((*transcoder).faac_enc) as ::core::ffi::c_int;
    }
    return DEFAULT_AAC_FRAME_SIZE;
}
unsafe extern "C" fn make_faac_config(
    mut sample_rate: ::core::ffi::c_int,
    mut channels: ::core::ffi::c_int,
) -> faac_encoder_config_t {
    return faac_encoder_config {
        sample_rate: sample_rate as uint32_t,
        num_channels: channels as uint32_t,
        bit_rate_per_channel: (if sample_rate >= 32000 as ::core::ffi::c_int {
            64000 as ::core::ffi::c_int
        } else {
            32000 as ::core::ffi::c_int
        }) as uint32_t,
        object_type: faac_object_type::FAAC_OBJ_AUTO,
    };
}
